def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_intervals = sorted(intervals)
        merged = [sorted_intervals[0]]
        for current in sorted_intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)
        return merged

    def subtract_from_single(interval, subtracts):
        start, end = interval
        if start >= end:
            return []

        current_ranges = [[start, end]]

        for sub_start, sub_end in subtracts:
            if sub_start >= sub_end:
                continue

            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if sub_end <= curr_start or sub_start >= curr_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    if curr_start < sub_start:
                        new_ranges.append([curr_start, sub_start])
                    if sub_end < curr_end:
                        new_ranges.append([sub_end, curr_end])

            current_ranges = new_ranges
            if not current_ranges:
                break

        return current_ranges

    a_filtered = [interval for interval in a if interval[0] < interval[1]]
    b_merged = merge_intervals([interval for interval in b if interval[0] < interval[1]])

    if not a_filtered:
        return []
    if not b_merged:
        return sorted(a_filtered)

    result = []
    for interval in a_filtered:
        result.extend(subtract_from_single(interval, b_merged))

    result = merge_intervals(result)
    return result

